using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Text.RegularExpressions;
using Virinco.WATS.Interface;

namespace Virinco.WATS.Converter.NI.TestStand
{
    /// <summary>
    /// Converter for TestStand HTML reports generated by the ATML-based stylesheet
    /// (e.g. Hitachi customised tr6_horizontal.xsl). Implements IReportConverter_v2.
    /// </summary>
    public class TeststandATMLHtmlConverter : IReportConverter_v2
    {
        private readonly Dictionary<string, string> _parameters;
        private const string FormatSignature = "uutTable";

        private static readonly Regex EventRegex = new Regex(
            @"(?:Begin Sequence:\s*(?<beginSeq>[^<\r\n]+)</span>)" +
            @"|(?:End Sequence:\s*(?<endSeq>[^<\r\n]+)</span>)" +
            @"|(?:<tr><td><a name=""ResultId\d+""></a>(?!<img)(?<stepName>[^<]+)</td>" +
             @"<td[^>]*>(?<status>Passed|Failed|Terminated|Error)</td>" +
             @"<td[^>]*>(?<meas>[^<]*)</td>" +
             @"<td[^>]*>(?<units>[^<]*)</td>" +
             @"<td[^>]*>(?<nominal>[^<]*)</td>" +
             @"<td[^>]*>(?<low>[^<]*)</td>" +
             @"<td[^>]*>(?<high>[^<]*)</td>" +
             @"<td[^>]*>(?<comp>[^<]*)</td>)",
            RegexOptions.IgnoreCase | RegexOptions.Compiled);

        private static readonly Regex HeaderFieldRegex = new Regex(
            @"<td[^>]*>([^<]+)</td>\s*<td[^>]*>(.*?)</td>",
            RegexOptions.IgnoreCase | RegexOptions.Compiled | RegexOptions.Singleline);

        public Dictionary<string, string> ConverterParameters { get { return _parameters; } }

        public TeststandATMLHtmlConverter() : this(new Dictionary<string, string>()) { }

        public TeststandATMLHtmlConverter(IDictionary<string, string> args)
        {
            _parameters = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
            _parameters["operationTypeCode"] = "10";
            if (args != null)
                foreach (var kv in args)
                    _parameters[kv.Key] = kv.Value;
        }

        public void CleanUp() { }

        public Report ImportReport(TDM api, Stream file)
        {
            string content;
            using (StreamReader reader = new StreamReader(file, detectEncodingFromByteOrderMarks: true))
                content = reader.ReadToEnd();

            if (content.IndexOf(FormatSignature, StringComparison.OrdinalIgnoreCase) < 0)
                return null;

            Match headerMatch = Regex.Match(content,
                @"<table[^>]*class=""uutTable""[^>]*>(.*?)</table>",
                RegexOptions.Singleline | RegexOptions.IgnoreCase);
            if (!headerMatch.Success)
                return null;

            var fields = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
            foreach (Match m in HeaderFieldRegex.Matches(headerMatch.Groups[1].Value))
            {
                string key = DecodeHtml(m.Groups[1].Value.Trim());
                string val = DecodeHtml(m.Groups[2].Value.Trim());
                if (!string.IsNullOrEmpty(key))
                    fields[key] = val;
            }

            string serialNumber = GetField(fields, "SERIAL NUMBER");
            string partNumber   = GetField(fields, "PART NUMBER");
            string revision     = GetField(fields, "REVISION", "A");
            string stationName  = GetField(fields, "STATION ID");
            string operatorName = GetField(fields, "OPERATOR");
            string uutResultStr = GetField(fields, "UUT RESULT", "Passed");
            string execTimeStr  = GetField(fields, "EXECUTION TIME", "0");
            string dateStr      = GetField(fields, "DATE");
            string timeStr      = GetField(fields, "TIME");

            double execTime = 0;
            Match execMatch = Regex.Match(execTimeStr, @"([\d.]+)");
            if (execMatch.Success)
                double.TryParse(execMatch.Groups[1].Value, NumberStyles.Float, CultureInfo.InvariantCulture, out execTime);

            DateTime startDateTime = DateTime.UtcNow;
            if (!string.IsNullOrEmpty(dateStr) && !string.IsNullOrEmpty(timeStr))
            {
                string combined = dateStr + " " + timeStr;
                if (!DateTime.TryParseExact(combined,
                        new string[] { "dddd, d MMMM yyyy HH:mm:ss", "dddd, dd MMMM yyyy HH:mm:ss" },
                        CultureInfo.InvariantCulture, DateTimeStyles.None, out startDateTime))
                    DateTime.TryParse(combined, CultureInfo.InvariantCulture, DateTimeStyles.None, out startDateTime);
            }

            UUTReport uutReport = api.CreateUUTReport(
                operatorName, partNumber, revision, serialNumber,
                _parameters["operationTypeCode"], stationName, "1.0");

            uutReport.StartDateTime = startDateTime;
            uutReport.ExecutionTime = execTime;
            uutReport.Status = ParseUUTStatus(uutResultStr);

            string product = GetField(fields, "PRODUCT");
            if (!string.IsNullOrEmpty(product))
                uutReport.AddMiscUUTInfo("PRODUCT", product);

            string testOperation = GetField(fields, "Test Operation");
            if (!string.IsNullOrEmpty(testOperation))
                uutReport.AddMiscUUTInfo("TestOperation", testOperation);

            SequenceCall rootSeq = uutReport.GetRootSequenceCall();
            int bodyStart = content.IndexOf("headerSeparator", StringComparison.OrdinalIgnoreCase);
            string body = bodyStart >= 0 ? content.Substring(bodyStart) : content;

            var seqStack = new Stack<SequenceCall>();
            bool rootNamed = false;

            foreach (Match m in EventRegex.Matches(body))
            {
                if (m.Groups["beginSeq"].Success)
                {
                    string seqName = DecodeHtml(m.Groups["beginSeq"].Value.Trim());
                    if (!rootNamed)
                    {
                        rootSeq.Name = seqName;
                        seqStack.Push(rootSeq);
                        rootNamed = true;
                    }
                    else
                    {
                        SequenceCall parent = seqStack.Count > 0 ? seqStack.Peek() : rootSeq;
                        seqStack.Push(parent.AddSequenceCall(seqName));
                    }
                }
                else if (m.Groups["endSeq"].Success)
                {
                    if (seqStack.Count > 1) seqStack.Pop();
                }
                else if (m.Groups["stepName"].Success)
                {
                    SequenceCall currentSeq = seqStack.Count > 0 ? seqStack.Peek() : rootSeq;
                    AddStep(currentSeq, m);
                }
            }

            return uutReport;
        }

        private static void AddStep(SequenceCall seq, Match m)
        {
            string stepName  = DecodeHtml(m.Groups["stepName"].Value.Trim());
            string statusStr = m.Groups["status"].Value;
            string measStr   = m.Groups["meas"].Value.Trim();
            string units     = DecodeHtml(m.Groups["units"].Value.Trim());
            string lowStr    = m.Groups["low"].Value.Trim();
            string highStr   = m.Groups["high"].Value.Trim();
            string compStr   = m.Groups["comp"].Value.Trim();
            bool   isPassed  = statusStr.Equals("Passed", StringComparison.OrdinalIgnoreCase);

            double measured;
            if (!string.IsNullOrEmpty(measStr) &&
                double.TryParse(measStr, NumberStyles.Float, CultureInfo.InvariantCulture, out measured))
            {
                double low, high;
                bool hasLow  = double.TryParse(lowStr,  NumberStyles.Float, CultureInfo.InvariantCulture, out low);
                bool hasHigh = double.TryParse(highStr, NumberStyles.Float, CultureInfo.InvariantCulture, out high);
                CompOperatorType compOp = ParseCompOp(compStr, hasLow, hasHigh);
                NumericLimitStep numStep = seq.AddNumericLimitStep(stepName);
                numStep.AddTest(measured, compOp,
                    hasLow  ? low  : double.NaN,
                    hasHigh ? high : double.NaN,
                    string.IsNullOrEmpty(units) ? null : units);
            }
            else
            {
                seq.AddPassFailStep(stepName).AddTest(isPassed);
            }
        }

        private static CompOperatorType ParseCompOp(string s, bool hasLow, bool hasHigh)
        {
            if (!string.IsNullOrEmpty(s))
            {
                if (s.StartsWith("GELE", StringComparison.OrdinalIgnoreCase)) return CompOperatorType.GELE;
                if (s.StartsWith("GELT", StringComparison.OrdinalIgnoreCase)) return CompOperatorType.GELT;
                if (s.StartsWith("GTLE", StringComparison.OrdinalIgnoreCase)) return CompOperatorType.GTLE;
                if (s.StartsWith("GTLT", StringComparison.OrdinalIgnoreCase)) return CompOperatorType.GTLT;
                if (s.StartsWith("GE",   StringComparison.OrdinalIgnoreCase)) return CompOperatorType.GE;
                if (s.StartsWith("GT",   StringComparison.OrdinalIgnoreCase)) return CompOperatorType.GT;
                if (s.StartsWith("LE",   StringComparison.OrdinalIgnoreCase)) return CompOperatorType.LE;
                if (s.StartsWith("LT",   StringComparison.OrdinalIgnoreCase)) return CompOperatorType.LT;
                if (s.StartsWith("EQ",   StringComparison.OrdinalIgnoreCase)) return CompOperatorType.EQ;
                if (s.StartsWith("NE",   StringComparison.OrdinalIgnoreCase)) return CompOperatorType.NE;
                if (s.StartsWith("LOG",  StringComparison.OrdinalIgnoreCase)) return CompOperatorType.LOG;
            }
            if (hasLow && hasHigh) return CompOperatorType.GELE;
            if (hasLow)            return CompOperatorType.GE;
            if (hasHigh)           return CompOperatorType.LE;
            return CompOperatorType.LOG;
        }

        private static UUTStatusType ParseUUTStatus(string s)
        {
            if (s.IndexOf("Pass",  StringComparison.OrdinalIgnoreCase) >= 0) return UUTStatusType.Passed;
            if (s.IndexOf("Fail",  StringComparison.OrdinalIgnoreCase) >= 0) return UUTStatusType.Failed;
            if (s.IndexOf("Error", StringComparison.OrdinalIgnoreCase) >= 0) return UUTStatusType.Error;
            return UUTStatusType.Terminated;
        }

        private static string GetField(Dictionary<string, string> d, string key, string fallback)
        {
            string v;
            return d.TryGetValue(key, out v) ? v : fallback;
        }

        private static string GetField(Dictionary<string, string> d, string key)
        {
            return GetField(d, key, string.Empty);
        }

        private static string DecodeHtml(string s)
        {
            if (string.IsNullOrEmpty(s)) return s;
            s = s.Replace("&nbsp;", " ").Replace("&amp;", "&")
                 .Replace("&lt;", "<").Replace("&gt;", ">")
                 .Replace("&apos;", "'").Replace("&quot;", "\"");
            return s.Trim();
        }
    }
}